// 不用虚拟回滚模拟报价；采用再次读取实际声明与原冻结两腿，迟到的bind/capture失败仍上交原事务。
#include "task_shop_order_business.hpp"
namespace hanmo::resident {namespace {
template<class T>Outcome<T> fail(const StableId& code){return {false,{},common_failure(code).error};}
bool same(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
const TaskShopOrderBinding* binding(const TaskShopOrderState& s,const StableId& task){auto at=s.by_task.find(task);return at==s.by_task.end()?nullptr:s.bindings.find(at->second);}
}
Outcome<TaskShopOrderQuote> preview_task_shop_order_business(const CommonStore& common,const TaskState& tasks,const TaskShopOrderState& state,const TaskShopOrderViewAccess& read,const StableId& actor,const TaskShopOrderCommand& command){
    TaskShopOrderQuote quote;quote.source_identity=common.state().identity;quote.actor_id=actor;quote.command=command;
    switch(command.kind){
    case TaskShopOrderCommand::Kind::accept:{auto prepared=preview_task_shop_order_acceptance(common,tasks,state,read.task_catalog,read.common_catalog,read.orders,read.acceptance_meeting,actor,command.id);if(!prepared.ok)return {false,{},prepared.error};quote.terms=prepared.value.terms;quote.acceptance=std::move(prepared.value);break;}
    case TaskShopOrderCommand::Kind::deliver:{auto prepared=preview_task_shop_order_delivery(common,tasks,state,read.orders,read.interaction,read.interaction_catalog,read.interaction_access,actor,command.id);if(!prepared.ok)return {false,{},prepared.error};const auto* source=binding(state,command.id);if(!source)return fail<TaskShopOrderQuote>("TaskShopOrderTaskMissing");quote.terms=source->terms;quote.delivery=std::move(prepared.value);break;}
    case TaskShopOrderCommand::Kind::cancel:{auto prepared=preview_task_shop_order_cancellation(common,tasks,state,read.orders,actor,command.id);if(!prepared.ok)return {false,{},prepared.error};const auto* source=binding(state,command.id);if(!source)return fail<TaskShopOrderQuote>("TaskShopOrderTaskMissing");quote.terms=source->terms;break;}
    default:return fail<TaskShopOrderQuote>("UnsupportedTaskShopOrderCommand");
    }
    return {true,std::move(quote),{}};
}
Outcome<TaskShopOrderCommit> commit_task_shop_order_business_in_candidate(CommonStore& common,TaskState& tasks,TaskShopOrderState& state,const TaskShopOrderViewAccess& read,const TaskShopOrderQuote& quote,const TaskShopOrderBusinessEffects& effects){
    if(!same(quote.source_identity,common.state().identity))return fail<TaskShopOrderCommit>("StaleTaskShopOrderQuote");auto current=preview_task_shop_order_business(common,tasks,state,read,quote.actor_id,quote.command);if(!current.ok)return {false,{},current.error};if(!task_shop_order_terms_equal(current.value.terms,quote.terms)||bool(quote.acceptance)!=(quote.command.kind==TaskShopOrderCommand::Kind::accept)||bool(quote.delivery)!=(quote.command.kind==TaskShopOrderCommand::Kind::deliver))return fail<TaskShopOrderCommit>("StaleTaskShopOrderQuote");
    TaskShopOrderCommit result;result.order_id=quote.terms.order_id;result.shop_id=quote.terms.shop_id;Status valid=common_success();
    switch(quote.command.kind){
    case TaskShopOrderCommand::Kind::accept:{if(!effects.bind)return fail<TaskShopOrderCommit>("TaskShopOrderBindingUnavailable");if(quote.acceptance->actor_id!=quote.actor_id||quote.acceptance->terms.order_id!=quote.command.id||!task_shop_order_terms_equal(quote.acceptance->terms,quote.terms))return fail<TaskShopOrderCommit>("StaleTaskShopOrderQuote");auto adopted=accept_task_shop_order_in_candidate(common,tasks,state,read.task_catalog,read.common_catalog,read.orders,read.acceptance_meeting,*quote.acceptance);if(!adopted.ok)return {false,{},adopted.error};valid=effects.bind(adopted.value);if(!valid.ok)return {false,{},valid.error};result.task_id=adopted.value.task_id;result.source_fact_id=adopted.value.acceptance_fact_id;break;}
    case TaskShopOrderCommand::Kind::deliver:{if(quote.delivery->contact.meeting.actor_id!=quote.actor_id||quote.delivery->task_id!=quote.command.id)return fail<TaskShopOrderCommit>("StaleTaskShopOrderQuote");auto started=begin_task_shop_order_delivery_in_candidate(common,tasks,state,read.orders,read.interaction,read.interaction_catalog,read.interaction_access,*quote.delivery);if(!started.ok)return {false,{},started.error};result.task_id=quote.command.id;result.action_id=started.value;break;}
    case TaskShopOrderCommand::Kind::cancel:{if(!effects.capture)return fail<TaskShopOrderCommit>("TaskShopOrderCaptureUnavailable");auto cancelled=cancel_task_shop_order_in_candidate(common,tasks,state,read.orders,quote.actor_id,quote.command.id);if(!cancelled.ok)return {false,{},cancelled.error};valid=effects.capture(cancelled.value);if(!valid.ok)return {false,{},valid.error};result.task_id=quote.command.id;result.source_fact_id=cancelled.value.receipt_fact_id;break;}
    default:return fail<TaskShopOrderCommit>("UnsupportedTaskShopOrderCommand");
    }
    valid=validate_task_shop_order_execution(common,tasks,state,read.orders);if(!valid.ok)return {false,{},valid.error};return {true,std::move(result),{}};
}
Outcome<TaskEffect> finish_task_shop_order_business_in_candidate(CommonStore& common,TaskState& tasks,TaskShopOrderState& state,const TaskShopOrderViewAccess& read,const StableId& action_id,const DynamicStepInput& phase,const TaskShopOrderExecutionCapture& capture){
    if(!capture)return fail<TaskEffect>("TaskShopOrderCaptureUnavailable");auto result=finish_task_shop_order_delivery_in_candidate(common,tasks,state,read.orders,read.interaction,read.interaction_catalog,read.interaction_access,action_id,phase);if(!result.ok)return result;if(result.value.success){if(!result.value.task_id)return fail<TaskEffect>("TaskShopOrderSettlementMissing");TaskShopOrderExecutionAccess executed(common,tasks,state,&phase);auto source=executed.private_shop_order_execution(*result.value.task_id);if(!source.ok)return {false,{},source.error};if(!source.value||source.value->outcome!="delivered")return fail<TaskEffect>("TaskShopOrderSettlementMissing");auto captured=capture(*source.value);if(!captured.ok)return {false,{},captured.error};}auto valid=validate_task_shop_order_execution(common,tasks,state,read.orders,&phase);if(!valid.ok)return {false,{},valid.error};return result;
}
BoundaryValue encode_task_shop_order_quote(const TaskShopOrderQuote& q){using V=BoundaryValue;return boundary::obj({{"duration",V{Integer{q.command.kind==TaskShopOrderCommand::Kind::deliver?1:0}}},{"order_id",V{q.terms.order_id}},{"task_id",V{q.command.kind==TaskShopOrderCommand::Kind::accept?StableId{}:q.command.id}},{"item_id",V{q.terms.item_id}},{"quantity",V{q.terms.quantity}},{"contract_price",V{q.terms.contract_price}},{"deadline_tick",V{q.terms.deadline_tick}}});}
}
